function sorted(l){var w={high:0,mid:1,low:2};return l.slice().sort(function(a,b){if(a.due!==b.due){if(!a.due)return 1;if(!b.due)return -1;return a.due<b.due?-1:1}if((a.time||"")!==(b.time||""))return(a.time||"99")<(b.time||"99")?-1:1;return(w[a.pri]-w[b.pri])||(a.created-b.created)})}
