 if(!D().goals.length&&Object.keys(a).length){var g=a.goal===undefined?4:a.goal;D().goals=[{id:uid(),title:"",k:"g"+g,pct:0},{id:uid(),title:"",k:"g3",pct:0}];if(g===3)D().goals.pop()}
