 s=s.replace(/(^|\s)#([\p{L}\p{N}_-]+)/gu,function(m,a,g){tags.push(g.toLowerCase());return a}).replace(/(^|\s)(\d{1,2}):(\d{2})(?=\s|$)/,function(m,a,h,mi){if(+h<24&&+mi<60)tm=pad(h)+":"+mi;return a}).replace(/\s+/g," ").trim();
 if(!s)s=el.value.trim();var pj=S.view==="inbox"?"":S.view.indexOf("p:")===0?S.view.slice(2):(proj("c_personal")?"c_personal":(D().projects[0]||{}).id||"");
