function saveTask(){var ti=$("mT").value.trim();if(!ti){$("mE").classList.remove("hid");$("mT").focus();return}
 var d={title:ti,desc:$("mD").value.trim(),due:$("mDue").value||"",time:$("mTm").value||"",pri:$("mP").value,proj:$("mL").value,tags:parseTags($("mG").value)};
 if(S.edit){var x=D().tasks.filter(function(y){return y.id===S.edit})[0];if(x)for(var k in d)x[k]=d[k]}else{d.id=uid();d.done=false;d.doneAt="";d.created=Date.now();D().tasks.push(d)}F.record(S.edit?"updated":"created",S.edit?x:d);persist();closeM();refresh()}
function delTask(id){var i=D().tasks.findIndex(function(y){return y.id===id});if(i<0)return;S.undo={x:D().tasks[i],i:i};F.record("deleted",D().tasks[i]);D().tasks.splice(i,1);persist();refresh();toast(t("deleted"),true)}
function closePops(){document.querySelectorAll('[data-act="pop"]').forEach(function(b){b.setAttribute("aria-expanded","false")});document.querySelectorAll(".pop").forEach(function(p){p.hidden=true})}
function closeKm(){var k=$("km");if(k)k.remove()}
function showKm(b,id){closeKm();var r=b.getBoundingClientRect(),k=document.createElement("div");k.className="km";k.id="km";k.innerHTML='<button data-act="editT" data-id="'+id+'">'+ic("edit")+t("edit")+'</button><button class="dn" data-act="delT" data-id="'+id+'">'+ic("del")+t("del")+'</button>';document.body.appendChild(k);k.style.top=Math.min(r.bottom+4,innerHeight-100)+"px";k.style.left=Math.max(8,Math.min(r.right-150,innerWidth-160))+"px"}
function finishSurvey(){D().survey={done:true,answers:S.sv.ans,at:Date.now()};S.retake=0;applySurvey();persist();S.view="today";render()}
