function readAuth(){var a=S.au;["User","Contact","Pass","Code"].forEach(function(k){var e=$("au"+k);if(e)a[{User:"username",Contact:"contact",Pass:"password",Code:"code"}[k]]=e.value})}
function checkContact(){var a=S.au,r;if(a.method==="email"){r=vEmail(a.contact);return r?{v:r}:{e:"eEmail"}}return vPhone(a.contact)}
function doReg(){if(S.au.busy)return;readAuth();var a=S.au,u=a.username.trim();if(!vUser(u))return err("eUser");var c=checkContact();if(c.e)return err(c.e);if(a.method==="email"&&!vPass(a.password))return err("ePass");
 a.busy=true;B.free(u).then(function(f){if(!f)throw{code:"eTaken"};return B.register({username:u,method:a.method,contact:c.v,password:a.password})}).then(function(r){a.step="verify";a.contact=c.v;a.username=u;a.demo=r.demoCode||"";a.mode=r.mode;a.err="";a.busy=false;a.code="";render()}).catch(function(x){err(x&&x.code&&T[x.code]?x.code:"eNet")})}
function doSend(){readAuth();if(S.au.busy)return;var a=S.au,c=checkContact();if(c.e)return err(c.e);a.contact=c.v;a.busy=true;B.loginStart(c.v).then(function(r){a.busy=false;a.sent=true;a.demo=r.demoCode||"";a.err="";S.keep=0;render()}).catch(function(x){err(x&&x.code&&T[x.code]?x.code:"eNet")})}
function doLogin(){if(S.au.busy)return;readAuth();var a=S.au,c=checkContact();if(c.e)return err(c.e);a.busy=true;B.login({method:a.method,contact:c.v,password:a.password,code:a.code}).then(function(u){a.busy=false;a.err="";return enter(u)}).catch(function(x){err(x&&x.code&&T[x.code]?x.code:"eNet")})}
function doConfirm(){readAuth();var a=S.au;B.confirm(a.code).then(function(u){a.step="form";a.password="";return enter(u)}).catch(function(x){err(x&&x.code&&T[x.code]?x.code:"eNet")})}
