 if(F.key(e))return;
 if(e.key==='Tab'&&!$('modal').hidden){var fs=modalFocusables();var first=fs[0],last=fs[fs.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
